        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)

import math


ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
EXIT_X_MIN = 15.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
TIME_STEP = 1.0 / 60.0


def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }


class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}


MEM = Memory()


def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)


def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)


def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    # Initialize fx for all cases
    fx = 0.0
    fy = 0.0

    # Approach phase: apply backward force to meet unlock condition
    if state["phase"] == "APPROACH":
        # Apply backward force when entering activation zone
        if 5.0 <= x <= 10.0:
            fx = -35.0  # Ensures Fx < -34.0 N
            fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
            # Check if unlock condition is met
            if (cfg["act_lo"] <= x <= cfg["act_hi"]) and (abs(vxd) < 0.1):
                state["phase"] = "UNLOCK"
                state["t"] = 0
        else:
            # Apply forward force to push into activation zone
            fx = 100.0 * (ACTIVATION_X_MIN - x) - 20.0 * vxd
            fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

    # Unlock phase: apply strict backward force to trigger unlock
    elif state["phase"] == "UNLOCK":
        fx = -35.0  # Ensures Fx < -34.0 N
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Keep unlock phase for 5 steps to allow momentum buildup
        state["t"] += 1
        if state["t"] > 5:
            state["phase"] = "ESCAPE"

    # Escape phase: apply forward force, adjusted for wall proximity
    elif state["phase"] == "ESCAPE":
        front, up, down = sandbox.get_whisker_readings()
        # Apply forward force of 80 N
        fx = 80.0
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust for wall proximity
        if front < 1.5:  # near the wall at x=9.0
            fx += 10.0  # +10 N lateral force
        # Check velocity to ensure sufficient acceleration
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        if spd < 0.1:
            fx = 90.0  # higher force to accelerate
        # Transition to hold phase when in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"

    # Hold phase: apply minimal force to maintain position in exit zone
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)
